<script lang="ts">import type { Snippet } from 'svelte'; import type { HTMLAttributes } from 'svelte/elements'; import { contains } from '../shared/dom.js'; import { getPopoverContext } from '../popover/popover-context.svelte.js'; export interface Props extends Omit<HTMLAttributes<HTMLDivElement>, 'children'> { children?: Snippet; ref?: HTMLDivElement | null; } let { children, ref = $bindable(null), ...rest }: Props = $props(); const popover = getPopoverContext(); function attach(node: HTMLDivElement) { const outside = (event: PointerEvent) => { if (!contains(node, event.target) && !contains(popover.trigger, event.target)) popover.setOpen(false, 'outside-press', event); }; document.addEventListener('pointerdown', outside, true); return () => document.removeEventListener('pointerdown', outside, true); }</script>
{#if popover.open}<div bind:this={ref} {...rest} data-open="" data-side={popover.side} data-align={popover.align} {@attach attach}>{@render children?.()}</div>{/if}
